-- Achievements window.
--
-- Mirrors game_bao / game_bazaar: one raw opcode claimed per direction via
-- ProtocolGame.registerOpcode, a sub-type byte inside the payload for routing,
-- and full state cached client-side and redrawn from cache rather than
-- re-requested on every filter change.
--
-- Reminder for anyone editing this file: the CLIENT runs Lua 5.1. Integer
-- division (//), goto and bitwise operators are all syntax errors here even
-- though the server's 5.5 accepts them.
--
-- The public catalogue is NOT received from the server -- it ships in
-- catalogue.lua, generated by tools/gen_achievement_catalogue.js. See the note
-- in data/scripts/network/achievements/achievements_protocol.lua for why. What
-- the server sends is everything personal: what is unlocked, when, how rare it
-- is, and the full text of secrets this character has actually earned.

-- 0x4A/0x4B (74/75 decimal): inside the OTClientV8-reserved custom opcode
-- range (0x40-0x4F), clear of 0x4C/0x4D (Bao) and 0x4F (Item Bazaar).
local OPCODE_ACHIEVEMENTS_REQUEST = 0x4A -- client -> server
local OPCODE_ACHIEVEMENTS_SEND = 0x4B    -- server -> client

local RESP_SYNC = 0x01
local RESP_SECRETS = 0x02
local RESP_HIGHSCORES = 0x03

local ACTION_REQUEST_SYNC = 0x01
local ACTION_SET_SHOWCASE = 0x02
local ACTION_REQUEST_HIGHSCORES = 0x03

-- The board this window opens on. Experience, matching the website's default,
-- and matching id 1 in data/lib/highscores/highscores_config.lua -- the ids
-- there are WIRE ids and are never recycled, so this constant is stable.
local DEFAULT_BOARD = 1

-- (!) The card spends colour ONCE, on the grade, and everything else is grey.
--
-- Points were full currency gold, the earned date was the positive green and
-- an unclaimed achievement wore the urgency amber -- three accents that all
-- mean something else everywhere in this client. Gold is money and this is not
-- money; green is a gain or the primary action and a date is neither; amber is
-- time pressure and "nobody has this yet" is not running out.
--
-- Points keep a trace of gold because a number worth scanning should not be
-- the same weight as a label, but at about a third of the saturation.
local COLOR_POINTS = '#c9ab73'
local COLOR_POINTS_DIM = '#7a6a4c'
local COLOR_EARNED = '#c8c8c8'
local COLOR_UNCLAIMED = '#9a9a9a'
local COLOR_META = '#9a9a9a'

-- Difficulty, in the two brightnesses a card can be drawn at. Grades beyond
-- the three the catalogue currently uses fall back to neutral rather than
-- silently borrowing another difficulty's colour.
-- rail / dim  the 3px bar down the card's left edge, earned and not
-- text / textDim  the same hue lifted far enough to READ as text on the grey
--   cap band. The rail values are surface colours -- #3f6b3a as a word on
--   #353535 is barely legible -- so the chip cannot simply borrow them.
local GRADES = {
  [1] = { name = 'Easy',   rail = '#3f6b3a', dim = '#2c4a29', text = '#83b877', textDim = '#5c7a56' },
  [2] = { name = 'Medium', rail = '#2f5a7d', dim = '#223f57', text = '#74a4c8', textDim = '#556f85' },
  [3] = { name = 'Hard',   rail = '#7a2c2c', dim = '#4f1d1d', text = '#c67f7f', textDim = '#855858' },
}
local GRADE_FALLBACK = { name = 'Unrated', rail = '#4a4a4a', dim = '#3a3a3a',
                         text = '#9a9a9a', textDim = '#6f6f6f' }

local SHOW_MODES = {
  { label = 'Everything', key = 'all' },
  { label = 'Earned',     key = 'earned' },
  { label = 'Not earned', key = 'locked' },
  { label = 'Secrets',    key = 'secrets' },
}

local SORT_MODES = {
  { label = 'Difficulty',   key = 'difficulty' },
  { label = 'Rarest first', key = 'rarest' },
  { label = 'Most common',  key = 'common' },
  { label = 'Most points',  key = 'points' },
  { label = 'Name',         key = 'name' },
  { label = 'Recent',       key = 'recent' },
}

-- ─── Virtual list geometry ──────────────────────────────────────────────
--
-- (!) The grid holds a POOL of cards -- about one screenful plus a spare row
-- either side -- and never one card per achievement.
--
-- The first version built a widget per entry: 242 cards of thirteen widgets
-- each, ~3,150 widgets in one panel. Nothing about that is free here:
--
--   * UIGridLayout::addWidget calls update(), and internalUpdate() walks EVERY
--     child calling setRect. Adding n cards is therefore O(n^2) -- ~29,000
--     card rects, each re-running that card's own anchor layout over its
--     thirteen children. That is the freeze on open and on every filter
--     change.
--
--   * Scrolling moves the panel's virtual offset, which re-runs the same
--     full-list internalUpdate. One wheel tick repositioned ~3,150 widgets,
--     queued a deferred onGeometryChange Lua call for each, and -- via the
--     containsPoint check at the end of UIWidget::setRect -- triggered a
--     full-tree hover recomputation for every card that crossed the cursor.
--     That is the lag while simply reading the list.
--
-- Drawing was never the problem: UIWidget::drawChildren already culls children
-- whose rect misses the visible rect. It is LAYOUT that scales with child
-- count, so the fix is to hold the child count still.
--
-- With a pool the numbers stop moving: ~15 cards, ~200 widgets, whatever the
-- catalogue grows to. A scroll repositions fifteen cards and refills at most
-- three of them per row crossed.

-- These mirror the grid's cell-size / cell-spacing / num-columns in
-- achievements.otui. They have to agree: the layout places the cards, this
-- module computes the scroll range and the row-to-entry mapping from the same
-- numbers, and a disagreement shows up as cards drifting away from the bar.
local CARD_HEIGHT = 122
local CARD_SPACING = 6
local CARD_COLS = 3
local ROW_PITCH = CARD_HEIGHT + CARD_SPACING

-- A partial row can hang off the top and another off the bottom at the same
-- time, so a screenful of rows needs two spares to cover both edges.
local OVERSCAN_ROWS = 2

local window = nil
local state = nil
local secrets = {}
local searchEvent = nil
local statusEvent = nil

-- The two tab panels.
--
-- (!) THEY ARE NOT ALWAYS CHILDREN OF `window`. UITabBar parents only the
-- SELECTED tab's panel into the content widget and detaches the other, so at
-- init -- with Highscores selected first -- the achievements panel is a live
-- but unparented widget, and `window:recursiveGetChildById('showFilter')`
-- returns nil there. That was the crash this replaced: populateFilters runs
-- during init and indexed a nil combo.
--
-- Declared up here rather than beside the highscores code below because
-- findWidget needs them, and findWidget is used from the first helper onward.
local hsPanel = nil
local achPanel = nil

-- Resolve a widget by id wherever it currently lives: the achievements panel
-- first (most lookups in this file are its widgets), then the window itself
-- for the shared chrome -- statusLine and closeButton are window children and
-- always have been.
local function findWidget(id)
  local widget = achPanel and achPanel:recursiveGetChildById(id)
  if widget then
    return widget
  end
  return window and window:recursiveGetChildById(id)
end

-- The virtual list. `visible` is the filtered, sorted entry list -- plain data,
-- one element per achievement. `pool` is the fixed set of card widgets drawn
-- over a moving window into it.
local visible = {}
local pool = {}
local poolFirstRow = -1
local scrollValue = 0
local suppressScrollEvent = false

-- ─── Helpers ────────────────────────────────────────────────────────────

local function comma(value)
  local formatted = tostring(math.floor(tonumber(value) or 0))
  local done
  repeat
    formatted, done = string.gsub(formatted, '^(-?%d+)(%d%d%d)', '%1,%2')
  until done == 0
  return formatted
end

local function percentOf(current, total)
  if not total or total <= 0 then
    return 0
  end
  return math.min(100, math.floor((current / total) * 100))
end

local function gradeInfo(grade)
  return GRADES[grade] or GRADE_FALLBACK
end

-- Permille in, display text out.
--
-- Permille rather than percent all the way from the database, because the
-- interesting end of this scale sits below one percent -- "0%" tells a player
-- nothing, "0.3%" tells them where to go next.
--
-- (!) "Nobody has this yet" is only true for someone who does not have it.
-- Rarity is recounted hourly, so a player who just earned something genuinely
-- rare sees a zero here for a while -- and telling them nobody has the thing
-- they are holding reads as a bug. Same fact, said from their side.
local function rarityText(permille, earned)
  if not permille or permille <= 0 then
    if earned then
      return 'First to earn this', COLOR_UNCLAIMED
    end
    return 'Nobody has this yet', COLOR_UNCLAIMED
  end
  if permille >= 10 then
    return string.format('%.0f%% have this', permille / 10), COLOR_META
  end
  return string.format('%.1f%% have this', permille / 10), COLOR_META
end

-- (!) Tooltips do not wrap. g_tooltip.display calls resizeToText() on a plain
-- single-line UILabel (corelib/ui/tooltip.lua), so a 250-character description
-- becomes a 250-character-wide label -- wider than the screen, which then also
-- pushes it off the left edge and cuts the start of the text off entirely.
-- Every multi-line tooltip in this window is wrapped by hand.
local TOOLTIP_WIDTH = 56

local function wrapText(text, width)
  width = width or TOOLTIP_WIDTH
  local lines = {}

  -- Paragraph breaks in the source survive; only the prose inside them wraps.
  for paragraph in string.gmatch(text .. '\n', '(.-)\n') do
    if paragraph == '' then
      lines[#lines + 1] = ''
    else
      local current = ''
      for word in string.gmatch(paragraph, '%S+') do
        if current == '' then
          current = word
        elseif #current + 1 + #word <= width then
          current = current .. ' ' .. word
        else
          lines[#lines + 1] = current
          current = word
        end
      end
      if current ~= '' then
        lines[#lines + 1] = current
      end
    end
  end

  return table.concat(lines, '\n')
end

-- A card gives the description four lines at this width; plenty run longer.
-- Cut at a word boundary with an ellipsis rather than letting the label clip
-- mid-word -- a trailing "..." reads as "there is more", a hard cut reads as a
-- rendering bug. The full text is on the card's tooltip either way.
local DESCRIPTION_LIMIT = 200

local function shortDescription(text)
  text = text or ''
  if #text <= DESCRIPTION_LIMIT then
    return text
  end
  local cut = string.sub(text, 1, DESCRIPTION_LIMIT)
  local lastSpace = string.find(string.reverse(cut), ' ')
  if lastSpace then
    cut = string.sub(cut, 1, #cut - lastSpace)
  end
  -- Trailing punctuation before an ellipsis reads as a typo.
  cut = string.gsub(cut, '[%s,;:%-]+$', '')
  return cut .. '...'
end

local function earnedText(timestamp)
  if not timestamp or timestamp <= 0 then
    return 'Earned'
  end
  return 'Earned ' .. os.date('%d %b %Y', timestamp)
end

-- The shipped catalogue is a list, and secrets arrive keyed by id. One lookup
-- over both, rebuilt whenever either changes.
local entryIndex = nil

-- Everything derived from the catalogue is built once and reused until a sync
-- changes it. Only two things can: a re-sync, and a page of secrets arriving.
--
-- entriesCache  the catalogue-plus-secrets list, so a keystroke does not
--               rebuild a 242-element table
-- searchIndex   name .. description, pre-lowercased, so a keystroke does not
--               re-lower ~60KB of prose
-- tooltipCache  the hand-wrapped card tooltip, which is the most expensive
--               string work per card and is identical every time it is built
local entriesCache = nil
local searchIndex = nil
local tooltipCache = nil

local function invalidateCatalogue()
  entryIndex = nil
  entriesCache = nil
  searchIndex = nil
  tooltipCache = nil
end

local function rebuildEntryIndex()
  entryIndex = {}
  for _, entry in ipairs(CATALOGUE) do
    entryIndex[entry.id] = entry
  end
  for id, entry in pairs(secrets) do
    entryIndex[id] = entry
  end
end

local function entryById(id)
  if not entryIndex then
    rebuildEntryIndex()
  end
  return entryIndex[id]
end

-- What the footer says when there is nothing transient to report.
--
-- The status line is the only permanent text in the window with room to teach
-- something, and showcasing is the one feature here a player would never find
-- on their own -- it lives behind a right-click.
local function baseStatus()
  if not state then
    return ''
  end
  if state.showcase and state.showcase > 0 then
    local entry = entryById(state.showcase)
    if entry then
      return 'Showcasing "' .. entry.name .. '" on your character page.'
    end
  end
  return 'Right-click an achievement you have earned to showcase it on your character page.'
end

local function setStatus(text)
  if not window then
    return
  end
  if statusEvent then
    removeEvent(statusEvent)
    statusEvent = nil
  end

  local line = findWidget('statusLine')
  if not text or text == '' then
    line:setText(baseStatus())
    return
  end

  line:setText(text)
  statusEvent = scheduleEvent(function()
    statusEvent = nil
    if window then
      findWidget('statusLine'):setText(baseStatus())
    end
  end, 6000)
end

local function sendAction(action, build)
  local protocol = g_game.getProtocolGame()
  if not protocol then
    return
  end
  local msg = OutputMessage.create()
  msg:addU8(OPCODE_ACHIEVEMENTS_REQUEST)
  msg:addU8(action)
  if build then
    build(msg)
  end
  protocol:send(msg)
end

-- 0 clears the nomination. The server validates ownership and answers with a
-- fresh sync either way, so the client never has to guess whether it took.
local function sendSetShowcase(achievementId)
  sendAction(ACTION_SET_SHOWCASE, function(msg) msg:addU16(achievementId or 0) end)
end

-- ─── Parsing ────────────────────────────────────────────────────────────

local function parseSync(msg)
  local parsed = {
    checksum = msg:getU32(),
    points = msg:getU16(),
    pointsTotal = msg:getU16(),
    unlocked = msg:getU16(),
    total = msg:getU16(),
    secretsUnlocked = msg:getU16(),
    secretsTotal = msg:getU16(),
    population = msg:getU16(),
    showcase = msg:getU16(),
    grades = {},
    unlockedAt = {},
    rarity = {},
  }

  local gradeCount = msg:getU8()
  for _ = 1, gradeCount do
    local grade = msg:getU8()
    parsed.grades[#parsed.grades + 1] = {
      grade = grade,
      unlocked = msg:getU16(),
      total = msg:getU16(),
    }
  end

  local unlockedCount = msg:getU16()
  for _ = 1, unlockedCount do
    local id = msg:getU16()
    parsed.unlockedAt[id] = msg:getU32()
  end

  local rarityCount = msg:getU16()
  for _ = 1, rarityCount do
    local id = msg:getU16()
    parsed.rarity[id] = msg:getU16()
  end

  return parsed
end

local function parseSecrets(msg)
  local last = msg:getU8()
  local count = msg:getU16()
  for _ = 1, count do
    local id = msg:getU16()
    local grade = msg:getU8()
    local points = msg:getU16()
    local name = msg:getString()
    local description = msg:getString()
    secrets[id] = {
      id = id,
      grade = grade,
      points = points,
      name = name,
      description = description,
      secret = true,
    }
  end
  return last == 1
end

-- ─── The entry list ─────────────────────────────────────────────────────

-- The shipped public catalogue plus every secret this character has revealed.
--
-- Secrets the player has NOT earned are absent by design: the server never
-- sends them and the client never ships them. The header's "Secrets 4 / 156"
-- is the only trace of them, which is exactly the tease it should be.
local function buildEntries()
  if entriesCache then
    return entriesCache
  end

  local entries = {}

  for _, entry in ipairs(CATALOGUE) do
    entries[#entries + 1] = entry
  end
  for _, entry in pairs(secrets) do
    entries[#entries + 1] = entry
  end

  rebuildEntryIndex()

  -- (!) Built here, in catalogue order, and never inside the filter loop.
  -- string.lower over every name and description on every keystroke is the
  -- kind of cost that hides behind a debounce until someone types quickly.
  searchIndex = {}
  for _, entry in ipairs(entries) do
    searchIndex[entry.id] =
      string.lower((entry.name or '') .. ' ' .. (entry.description or ''))
  end

  entriesCache = entries
  return entries
end

local function isEarned(entry)
  return state ~= nil and state.unlockedAt[entry.id] ~= nil
end

local function selectedOption(id, modes, fallback)
  if not window then
    return fallback
  end
  local combo = findWidget(id)
  local option = combo and combo:getCurrentOption()
  if not option then
    return fallback
  end
  for _, mode in ipairs(modes) do
    if mode.label == option.text then
      return mode.key
    end
  end
  return fallback
end

local function searchTerm()
  if not window then
    return ''
  end
  local text = findWidget('searchEdit'):getText() or ''
  return string.lower(text)
end

local function filterEntries(entries)
  local show = selectedOption('showFilter', SHOW_MODES, 'all')
  local term = searchTerm()
  local out = {}

  for _, entry in ipairs(entries) do
    local earned = isEarned(entry)
    local keep = true

    if show == 'earned' then
      keep = earned
    elseif show == 'locked' then
      keep = not earned
    elseif show == 'secrets' then
      keep = entry.secret == true
    end

    if keep and term ~= '' then
      local haystack = searchIndex and searchIndex[entry.id]
      keep = haystack ~= nil and string.find(haystack, term, 1, true) ~= nil
    end

    if keep then
      out[#out + 1] = entry
    end
  end

  return out
end

-- Sorts in place. Every comparator ends on the achievement id so the ordering
-- is total: table.sort is not stable, so two entries tying on the visible key
-- would otherwise swap places on every redraw.
local function sortEntries(entries, mode)
  local rarity = state and state.rarity or {}
  local unlockedAt = state and state.unlockedAt or {}

  table.sort(entries, function(a, b)
    if mode == 'rarest' or mode == 'common' then
      -- Unclaimed (permille 0) is the rarest thing on the board, not the most
      -- common -- so it sorts to the front of "rarest" and the back of
      -- "common", which a plain numeric compare would get backwards.
      local ra = rarity[a.id] or 0
      local rb = rarity[b.id] or 0
      if ra ~= rb then
        if mode == 'rarest' then
          return ra < rb
        end
        return ra > rb
      end
    elseif mode == 'points' then
      if a.points ~= b.points then
        return a.points > b.points
      end
    elseif mode == 'name' then
      if a.name ~= b.name then
        return a.name < b.name
      end
    elseif mode == 'recent' then
      local ta = unlockedAt[a.id] or 0
      local tb = unlockedAt[b.id] or 0
      if ta ~= tb then
        return ta > tb
      end
    else
      if a.grade ~= b.grade then
        return a.grade < b.grade
      end
      if a.points ~= b.points then
        return a.points < b.points
      end
    end
    return a.id < b.id
  end)
end

-- ─── Drawing ────────────────────────────────────────────────────────────

local function fillCard(card, entry)
  local earned = isEarned(entry)
  local info = gradeInfo(entry.grade)
  local cap = card:getChildById('cap')

  -- (!) Earned / unearned / showcased are widget STATES, not colours set from
  -- here.
  --
  -- UIWidget::updateStyle (uiwidget.cpp:1551) rebuilds the widget's style from
  -- scratch on every state change: it restores the base value of every tag any
  -- state block declares, then re-merges the blocks that currently match. The
  -- card's ground is image-color now, and $hover declares image-color -- so a
  -- colour set from Lua would survive exactly until the first time the mouse
  -- crossed the card, then vanish, with nothing to say why. (That is the same
  -- trap the old border-colour version of this hit; the fix then was to move
  -- to background-color, which no state declared.)
  --
  -- Driving it through setOn/setChecked puts the values inside the style,
  -- where the rebuild re-applies them, and lets $hover brighten all three
  -- grounds without knowing which one it is on. The rail stays a Lua fill: it
  -- is a genuine 3px accent bar, not a surface, and no state block touches it.
  local showcased = earned and state and state.showcase == entry.id

  card:getChildById('rail'):setBackgroundColor(earned and info.rail or info.dim)
  card:setOn(earned)
  card:setChecked(showcased)

  local grade = cap:getChildById('grade')
  grade:setText(info.name)
  -- No +14 of pill padding any more: the chip has no fill to pad.
  grade:setWidth(grade:getTextSize().width)
  grade:setColor(earned and info.text or info.textDim)

  local secret = cap:getChildById('secret')
  secret:setVisible(entry.secret == true)
  if entry.secret then
    secret:setWidth(secret:getTextSize().width)
    secret:setColor(earned and '#9a9a9a' or '#6f6f6f')
  end

  local showcaseChip = cap:getChildById('showcase')
  showcaseChip:setVisible(showcased)
  if showcased then
    showcaseChip:setWidth(showcaseChip:getTextSize().width)
  end

  local points = cap:getChildById('points')
  points:setText(entry.points .. (entry.points == 1 and ' pt' or ' pts'))
  points:setColor(earned and COLOR_POINTS or COLOR_POINTS_DIM)

  local name = card:getChildById('name')
  name:setText(entry.name)
  name:setColor(earned and '#f6f1e2' or '#7a7a7a')

  local description = card:getChildById('description')
  description:setText(shortDescription(entry.description))
  description:setColor(earned and '#8f8f8f' or '#5f5f5f')

  local foot = card:getChildById('foot')
  local rarity = foot:getChildById('rarity')
  local text, color = rarityText(state and state.rarity[entry.id], earned)
  rarity:setText(text)
  rarity:setColor(earned and color or (color == COLOR_UNCLAIMED and COLOR_UNCLAIMED or '#6f6f6f'))

  local status = foot:getChildById('status')
  if earned then
    status:setText(earnedText(state.unlockedAt[entry.id]))
    status:setColor(COLOR_EARNED)
  else
    status:setText('')
  end
  -- Earned-ness is carried by the card's own brightness ($on swaps the frame
  -- tint) and by the name and description contrast, not by a green date. A
  -- date that only appears when you have the thing does not also need a colour
  -- to say so.

  -- The card shows four lines of a description that sometimes runs to eight,
  -- so the tooltip carries the whole thing. It does NOT repeat the name --
  -- that is on the card an inch away -- and the rarity denominator is one
  -- short line, because a percentage nobody can size is just decoration.
  local tooltip = tooltipCache and tooltipCache[entry.id]
  if not tooltip then
    tooltip = entry.description or ''
    if state and state.population and state.population > 0 then
      tooltip = tooltip .. '\n\nRarity across ' .. comma(state.population) ..
        ' characters past level 8.'
    end
    tooltip = wrapText(tooltip)
    tooltipCache = tooltipCache or {}
    tooltipCache[entry.id] = tooltip
  end
  card:setTooltip(tooltip)

  -- Showcasing lives on right-click rather than on a button.
  --
  -- A control on the card would mean one on every card in a grid whose whole
  -- job is to stay scannable -- and it would sit on locked cards too, where it
  -- means nothing. Right-click is the idiom players already use on every item and
  -- creature in the client, and the status line below says it out loud.
  if earned then
    card.onMouseRelease = function(self, mousePosition, mouseButton)
      if mouseButton ~= MouseRightButton then
        return false
      end

      local menu = g_ui.createWidget('PopupMenu')
      menu:setGameMenu(true)
      if showcased then
        menu:addOption(tr('Remove from my character page'), function()
          sendSetShowcase(0)
        end)
      else
        menu:addOption(tr('Showcase on my character page'), function()
          sendSetShowcase(entry.id)
        end)
      end
      menu:display(mousePosition)
      return true
    end
  else
    card.onMouseRelease = nil
  end
end

-- ─── The virtual list ───────────────────────────────────────────────────

local function listPanel()
  return window and findWidget('cardList') or nil
end

local function scrollBar()
  return window and findWidget('cardScroll') or nil
end

-- Rows that fit on screen, plus the overscan.
--
-- Read off the live panel rather than derived from the window size, so this
-- keeps working if the window ever becomes resizable. The fallback covers the
-- one moment the panel has no height yet -- the pool is sized before the first
-- draw, and a zero here would build a pool of two cards.
local function poolRowsNeeded(list)
  local height = list:getHeight()
  if height <= 0 then
    height = 480
  end
  return math.ceil(height / ROW_PITCH) + OVERSCAN_ROWS
end

-- Grows or shrinks the pool to `rows` worth of cards.
--
-- (!) Cards are only ever appended to, or destroyed from, the TAIL.
-- UIGridLayout assigns cells in parent child-list order, so a card's position
-- in `pool` IS its cell; inserting in the middle would renumber every slot
-- after it.
local function resizePool(list, rows)
  local wanted = rows * CARD_COLS

  while #pool > wanted do
    local card = table.remove(pool)
    card:destroy()
  end

  while #pool < wanted do
    local card = g_ui.createWidget('AchCard', list)
    card.boundId = nil
    card.slotShown = true
    pool[#pool + 1] = card
  end
end

-- Points every pooled card at the entry belonging to its slot, and refills it
-- only when that actually changed. Scrolling one row past a card leaves the
-- other twelve untouched -- three fillCard calls per row crossed, not 242.
local function bindPool(firstRow, force)
  local base = firstRow * CARD_COLS

  for slot = 1, #pool do
    local card = pool[slot]
    local entry = visible[base + slot]
    local shown = entry ~= nil

    if shown then
      if force or card.boundId ~= entry.id then
        card.boundId = entry.id
        fillCard(card, entry)
      end
    else
      card.boundId = nil
    end

    -- (!) Hidden, never destroyed -- and only touched when the flag actually
    -- flips, because setVisible runs a layout pass. UIGridLayout skips
    -- invisible children without consuming a cell, so trailing blanks cost
    -- nothing and leave the filled slots exactly where they are, which is
    -- what a short final row needs.
    if card.slotShown ~= shown then
      card.slotShown = shown
      card:setVisible(shown)
    end
  end
end

-- Applies a scroll position. Whole rows change which entries are bound; the
-- remainder is a pixel offset the grid layout applies to the pool as a whole.
local function applyScroll()
  local list = listPanel()
  if not list then
    return
  end

  local row = math.floor(scrollValue / ROW_PITCH)
  local offset = scrollValue - row * ROW_PITCH

  if row ~= poolFirstRow then
    poolFirstRow = row
    bindPool(row, false)
  end

  -- (!) This is what lets the stock grid layout drive a virtual list. The
  -- cards keep cell indices 0..n forever and the panel's virtual offset is
  -- what slides them, so the offset only ever has to cover one row of travel
  -- -- and the layout pass it triggers walks fifteen children, not 242.
  list:setVirtualOffset({ x = 0, y = offset })
end

-- The scrollbar is driven by hand rather than by ScrollablePanel, which sizes
-- its range from getChildrenRect -- and getChildrenRect now describes the
-- pool, which is one screenful. The range has to describe the whole list.
local function updateScrollRange(list, bar)
  local rows = math.ceil(#visible / CARD_COLS)
  local content = rows > 0 and (rows * ROW_PITCH - CARD_SPACING) or 0
  local maxScroll = math.max(0, content - math.max(list:getHeight(), 0))

  -- setMaximum clamps the current value and fires onValueChange when it does;
  -- the guard keeps that from re-entering applyScroll mid-rebuild.
  suppressScrollEvent = true
  bar:setMinimum(0)
  bar:setMaximum(maxScroll)
  suppressScrollEvent = false

  if scrollValue > maxScroll then
    scrollValue = maxScroll
  end
end

local function drawCards()
  if not window or not state then
    return
  end

  local list = listPanel()
  local bar = scrollBar()
  if not list or not bar then
    return
  end

  visible = filterEntries(buildEntries())
  sortEntries(visible, selectedOption('sortMode', SORT_MODES, 'difficulty'))

  local notice = findWidget('emptyNotice')
  if #visible == 0 then
    notice:setText('Nothing matches that. Try a different filter, or clear the search.')
    notice:show()
  else
    notice:hide()
  end

  findWidget('shownCount'):setText(
    #visible == 1 and '1 achievement' or (comma(#visible) .. ' achievements'))

  resizePool(list, poolRowsNeeded(list))

  -- Back to the top on every redraw: a filter or sort change replaces the list
  -- under the scrollbar, and holding the old pixel offset would drop the
  -- player into the middle of a set they have not seen the start of.
  scrollValue = 0
  updateScrollRange(list, bar)
  suppressScrollEvent = true
  bar:setValue(0)
  suppressScrollEvent = false

  -- force: the pool still holds the previous list's cards, and an unchanged
  -- entry id is no promise that its earned state, rarity or showcase chip did
  -- not move underneath it.
  poolFirstRow = 0
  bindPool(0, true)
  list:setVirtualOffset({ x = 0, y = 0 })
end

local function drawHeader()
  if not window or not state then
    return
  end

  findWidget('pointsValue'):setText(comma(state.points))
  findWidget('pointsOf'):setText('of ' .. comma(state.pointsTotal))

  local unlockedPlate = findWidget('unlockedPlate')
  unlockedPlate:getChildById('caption'):setText('Unlocked')
  unlockedPlate:getChildById('value'):setText(comma(state.unlocked) .. ' / ' .. comma(state.total))

  local secretsPlate = findWidget('secretsPlate')
  secretsPlate:getChildById('caption'):setText('Secrets')
  secretsPlate:getChildById('value'):setText(
    comma(state.secretsUnlocked) .. ' / ' .. comma(state.secretsTotal))

  local secretHelp = wrapText(
    'Secret achievements are not listed until you earn one. Their names and ' ..
    'descriptions arrive only once they are yours.')
  secretsPlate:setTooltip(secretHelp)
  secretsPlate:getChildById('value'):setTooltip(secretHelp)

  local unlockedHelp = wrapText('Every achievement in the game, secret ones included.')
  unlockedPlate:setTooltip(unlockedHelp)
  unlockedPlate:getChildById('value'):setTooltip(unlockedHelp)

  -- The three difficulty meters. Driven entirely by what the server sent, so
  -- adding a fourth grade to the catalogue needs no client change beyond a
  -- colour -- the meter for it simply stays hidden until a slot exists.
  local meterIds = { 'gradeEasy', 'gradeMedium', 'gradeHard' }
  for index, id in ipairs(meterIds) do
    local meter = findWidget(id)
    local row = state.grades[index]
    if row then
      local info = gradeInfo(row.grade)
      meter:setVisible(true)
      meter:getChildById('caption'):setText(info.name)
      meter:getChildById('count'):setText(comma(row.unlocked) .. ' / ' .. comma(row.total))
      local bar = meter:getChildById('track'):getChildById('bar')
      bar:setBackgroundColor(info.rail)
      bar:setPercent(percentOf(row.unlocked, row.total))
    else
      meter:setVisible(false)
    end
  end
end

local function redraw()
  drawHeader()
  drawCards()
  -- Re-derives the footer from the new state, which is what makes the
  -- "Showcasing ..." line follow a nomination without a bespoke message.
  setStatus(nil)
end

-- ─── Events ─────────────────────────────────────────────────────────────

function onFilterChanged()
  drawCards()
end

-- Debounced. The redraw itself is cheap now that the grid is pooled, but the
-- filter and sort behind it still walk and re-order the whole catalogue, and
-- doing that per keystroke makes typing feel like wading. 180ms is below the
-- point a pause is noticed and above the interval between keys at normal
-- typing speed.
function onSearchChanged()
  if searchEvent then
    removeEvent(searchEvent)
  end
  searchEvent = scheduleEvent(function()
    searchEvent = nil
    drawCards()
  end, 180)
end


-- ─── Highscores tab ─────────────────────────────────────────────────────
--
-- Rides the achievements opcode pair (see the note at the top of
-- data/scripts/network/achievements/achievements_protocol.lua). One request
-- returns everything the tab draws: the board catalogue, the vocation list,
-- one page of rows, the leader, and where this character stands.
--
-- The catalogue is NOT shipped in the client the way the achievement
-- catalogue is. It is fourteen short rows rather than 71.7 KB, and it is
-- authored in one place on the server -- data/lib/highscores/
-- highscores_config.lua -- which is the same table the website renders from.
-- A client-side copy would be a third copy of a list that already had two.

-- hsPanel and achPanel are declared with `window` near the top of the file,
-- because findWidget needs them before this point.
local hs = nil
local hsRows = {}

local function hsBoardById(id)
  if not hs then
    return nil
  end
  for _, board in ipairs(hs.boards) do
    if board.id == id then
      return board
    end
  end
  return nil
end

local function requestHighscores(boardId, vocationId, page)
  sendAction(ACTION_REQUEST_HIGHSCORES, function(msg)
    msg:addU8(boardId or 0)
    msg:addU8(vocationId or 0)
    msg:addU8(page or 1)
  end)
end

local function parseHighscores(msg)
  local data = { boards = {}, vocations = {}, rows = {} }

  local boardCount = msg:getU8()
  for _ = 1, boardCount do
    table.insert(data.boards, {
      id = msg:getU8(),
      label = msg:getString(),
      title = msg:getString(),
      unit = msg:getString(),
      extraLabel = msg:getString(),
      group = msg:getString(),
      vocation = msg:getU8() == 1,
    })
  end

  data.board = msg:getU8()
  data.vocation = msg:getU8()
  data.page = msg:getU8()

  local vocationCount = msg:getU8()
  for _ = 1, vocationCount do
    table.insert(data.vocations, { id = msg:getU8(), name = msg:getString() })
  end

  local rowCount = msg:getU8()
  for _ = 1, rowCount do
    table.insert(data.rows, {
      rank = msg:getU16(),
      name = msg:getString(),
      level = msg:getU16(),
      vocation = msg:getString(),
      -- Strings, not numbers: a level-5,000 character's experience overflows
      -- U32 and every high-level row showed the identical clamped
      -- 4,294,967,295. The server formats them because it knows what each
      -- board's column means.
      value = msg:getString(),
      extra = msg:getString(),
    })
  end

  if msg:getU8() == 1 then
    data.champion = {
      name = msg:getString(),
      level = msg:getU16(),
      vocation = msg:getString(),
      value = msg:getString(),
      outfit = {
        type = msg:getU16(),
        head = msg:getU8(),
        body = msg:getU8(),
        legs = msg:getU8(),
        feet = msg:getU8(),
        addons = msg:getU8(),
      },
    }
  end

  if msg:getU8() == 1 then
    data.mine = { rank = msg:getU16(), value = msg:getString() }
  end

  return data
end

-- The board keys. Everything outside the `mastery` family gets a button;
-- mastery collapses into the Skills chooser beside them, which is the same
-- split the website makes for the same reason -- eight skills are a set you
-- pick one of, not eight destinations.
-- (!) The buttons are built ONCE and then only re-checked. They used to be
-- destroyed and recreated on every redraw, and that is what made a single
-- click feel like two.
--
-- The sequence was: press (the $pressed clip and its 1px text drop), release,
-- onClick sends the request -- and then, a full network round trip later, the
-- reply calls redrawHighscores -> fillBoardButtons -> destroyChildren(). Every
-- button under the cursor was replaced by a brand new widget, which starts
-- with no hover state and only re-acquires it on the next mouse event. So the
-- player saw a second, delayed state change they had not caused, arriving
-- late enough to read as a second press rather than as a redraw. The widths
-- being recomputed from getTextSize() made the whole row twitch with it.
--
-- The board catalogue is server-authoritative but does not change inside a
-- session, so the rebuild was pure cost. It is now keyed on the actual list:
-- if the ids and labels are the same, the widgets are kept and only their
-- checked state moves.
local boardButtonSignature = nil

local function fillBoardButtons()
  local row = hsPanel:recursiveGetChildById('boardButtons')

  local ids = {}
  for _, board in ipairs(hs.boards) do
    if board.group ~= 'mastery' then
      ids[#ids + 1] = board.id .. '=' .. board.label
    end
  end
  local signature = table.concat(ids, '|')

  if signature ~= boardButtonSignature then
    boardButtonSignature = signature
    row:destroyChildren()
    for _, board in ipairs(hs.boards) do
      if board.group ~= 'mastery' then
        local button = g_ui.createWidget('HsBoardButton', row)
        button:setId('board' .. board.id)
        button:setText(board.label)
        button:setWidth(button:getTextSize().width + 18)
        local id = board.id
        button.onClick = function()
          requestHighscores(id, 0, 1)
        end
      end
    end
  end

  -- HsBoardButton adds the $checked state AchButton lacks; without it
  -- setChecked would be a no-op and the open board would look identical
  -- to every board you are not on.
  for _, board in ipairs(hs.boards) do
    if board.group ~= 'mastery' then
      local button = row:getChildById('board' .. board.id)
      if button then
        button:setChecked(board.id == hs.board)
      end
    end
  end
end

local function fillSkillFilter()
  local combo = hsPanel:recursiveGetChildById('skillFilter')
  combo:clearOptions()

  local current = hsBoardById(hs.board)
  local onSkill = current and current.group == 'mastery'

  -- An inert first option, exactly like the website's: it names the control
  -- when no skill is open, and choosing it navigates nowhere.
  combo:addOption('Skills', 0)
  for _, board in ipairs(hs.boards) do
    if board.group == 'mastery' then
      combo:addOption(board.label, board.id)
    end
  end

  combo.onOptionChange = nil
  if onSkill then
    combo:setCurrentOption(current.label, true)
  else
    combo:setCurrentOption('Skills', true)
  end

  combo.onOptionChange = function(_, _, data)
    local boardId = tonumber(data) or 0
    if boardId > 0 and boardId ~= hs.board then
      requestHighscores(boardId, 0, 1)
    end
  end
end

local function fillVocationFilter()
  local combo = hsPanel:recursiveGetChildById('vocationFilter')
  local board = hsBoardById(hs.board)

  combo:clearOptions()
  combo.onOptionChange = nil

  if not board or not board.vocation then
    -- Account-scoped boards have no vocation axis at all, so the control is
    -- disabled rather than shown offering a filter that would be ignored.
    combo:addOption('All vocations', 0)
    combo:setCurrentOption('All vocations', true)
    combo:setEnabled(false)
    return
  end

  combo:setEnabled(true)
  combo:addOption('All vocations', 0)
  for _, voc in ipairs(hs.vocations) do
    combo:addOption(voc.name, voc.id)
  end

  local currentName = 'All vocations'
  for _, voc in ipairs(hs.vocations) do
    if voc.id == hs.vocation then
      currentName = voc.name
    end
  end
  combo:setCurrentOption(currentName, true)

  combo.onOptionChange = function(_, _, data)
    local vocationId = tonumber(data) or 0
    if vocationId ~= hs.vocation then
      requestHighscores(hs.board, vocationId, 1)
    end
  end
end

local function fillChampion()
  local plate = hsPanel:recursiveGetChildById('champPlate')
  local champion = hs.champion

  -- No leader, no plate. A board where nobody has scored ranks everyone at
  -- zero and every row ties at rank 1; the server refuses to name a champion
  -- there, and the plate collapses rather than standing empty.
  if not champion then
    plate:setVisible(false)
    plate:setHeight(0)
    return
  end

  plate:setVisible(true)
  plate:setHeight(96)

  local board = hsBoardById(hs.board)
  local creature = hsPanel:recursiveGetChildById('champCreature')
  if champion.outfit and champion.outfit.type and champion.outfit.type > 0 then
    creature:setOutfit(champion.outfit)
    creature:setVisible(true)
  else
    creature:setVisible(false)
  end

  hsPanel:recursiveGetChildById('champName'):setText(champion.name)
  hsPanel:recursiveGetChildById('champSub'):setText(
    'Level ' .. comma(champion.level) .. ' ' .. champion.vocation)
  hsPanel:recursiveGetChildById('champValue'):setText(champion.value)
  hsPanel:recursiveGetChildById('champUnit'):setText(board and board.unit or '')
end

local function fillRows()
  local list = hsPanel:recursiveGetChildById('rowList')
  local notice = hsPanel:recursiveGetChildById('hsNotice')

  list:destroyChildren()
  hsRows = {}

  if #hs.rows == 0 then
    notice:setText('Nobody has made this board yet.')
    notice:show()
    return
  end
  notice:hide()

  for index, row in ipairs(hs.rows) do
    local widget = g_ui.createWidget('HsRow', list)
    -- Banding by index rather than by rank: ties share a rank, so banding on
    -- rank would put two identical stripes side by side.
    -- (!) A TRANSLUCENT band over the list's own sunken ground, not two opaque
    -- greys. This is the client's own table idiom (data/styles/20-tables.otui
    -- runs TableRow at even: alpha / odd: #00000022), and it matters here
    -- because the list is a real surface now: two opaque fills would paper
    -- over the texture and the banding would read as two flat rectangles.
    widget:setBackgroundColor(index % 2 == 0 and '#00000022' or 'alpha')
    widget:getChildById('rank'):setText(row.rank .. '.')
    widget:getChildById('name'):setText(row.name)
    widget:getChildById('vocation'):setText(row.vocation)
    widget:getChildById('extra'):setText(row.extra)
    widget:getChildById('value'):setText(row.value)
    table.insert(hsRows, widget)
  end
end

local function fillYourRank()
  local text = hsPanel:recursiveGetChildById('youText')
  local board = hsBoardById(hs.board)

  if not hs.mine then
    -- An account-scoped board ranks accounts, not characters, so there is no
    -- "your rank" to state. Detected by the board having no vocation axis
    -- rather than by its id, so a second account-scoped board would say the
    -- right thing without this line being touched.
    if board and not board.vocation then
      text:setText(board.title .. ' is ranked per account, not per character.')
    else
      text:setText('You are not ranked on this board yet.')
    end
    return
  end

  text:setText(string.format('You are ranked %d with %s %s',
    hs.mine.rank, hs.mine.value,
    string.lower(board and board.unit or 'points')))
end

local function redrawHighscores()
  if not hs or not hsPanel then
    return
  end

  local board = hsBoardById(hs.board)
  hsPanel:recursiveGetChildById('headValue'):setText(board and board.unit or '')
  hsPanel:recursiveGetChildById('headExtra'):setText(board and board.extraLabel or '')

  fillBoardButtons()
  fillSkillFilter()
  fillVocationFilter()
  fillChampion()
  fillRows()
  fillYourRank()
end
local function onAchievementsOpcode(protocol, msg)
  local responseType = msg:getU8()

  if responseType == RESP_SYNC then
    state = parseSync(msg)
    -- Secrets arrive in their own messages straight after. Clearing here (and
    -- not on each page) is what stops a secret that was somehow removed from
    -- lingering in the list across a re-sync.
    secrets = {}
    -- The entry list, the search index and the tooltips are all derived from
    -- the catalogue plus what just arrived, so they die with the old state.
    invalidateCatalogue()
    redraw()

    if state.checksum ~= CATALOGUE_CHECKSUM then
      setStatus('This client\'s achievement list is out of date - some names and ' ..
        'descriptions may be wrong. Restart to update.')
    end
  elseif responseType == RESP_SECRETS then
    -- Redraw on the final page only. Redrawing per page would rebuild the
    -- whole grid several times over for a single sync.
    if parseSecrets(msg) then
      invalidateCatalogue()
      redraw()
    end
  elseif responseType == RESP_HIGHSCORES then
    hs = parseHighscores(msg)
    redrawHighscores()
  end

  return true
end

-- ─── Module lifecycle ───────────────────────────────────────────────────

local function populateFilters()
  local showCombo = findWidget('showFilter')
  showCombo:clearOptions()
  for _, mode in ipairs(SHOW_MODES) do
    showCombo:addOption(mode.label)
  end
  showCombo:setCurrentOption(SHOW_MODES[1].label, true)
  showCombo.onOptionChange = function() onFilterChanged() end

  local sortCombo = findWidget('sortMode')
  sortCombo:clearOptions()
  for _, mode in ipairs(SORT_MODES) do
    sortCombo:addOption(mode.label)
  end
  sortCombo:setCurrentOption(SORT_MODES[1].label, true)
  sortCombo.onOptionChange = function() onFilterChanged() end

  local search = findWidget('searchEdit')
  search.onTextChange = function() onSearchChanged() end
end

-- (!) The same fix game_bao needed.
--
-- UIWidget::recursiveFocus walks UP the parent chain on mouse press and lets
-- the first FOCUSABLE ancestor take focus; UIScrollArea:onChildFocusChange
-- then calls ensureChildVisible on it. In a tall grid that scrolls the list
-- hard mid-click, so content moves under the cursor and the release lands on a
-- different widget than the press. Disabling the handler on the scroll area
-- itself is the fix that cannot be defeated by nesting a panel in later.
local function stopFocusScrolling()
  local list = findWidget('cardList')
  if list then
    list.onChildFocusChange = function() end
  end
end

-- (!) The scroll area's own scrollbar binding is deliberately NOT used -- the
-- `vertical-scrollbar` tag is gone from achievements.otui.
--
-- UIScrollArea:updateScrollBars sizes the bar from getChildrenRect, which with
-- a pooled list is one screenful no matter how long the list is: the bar would
-- claim there is nothing to scroll. Everything the binding would have given us
-- is reproduced here against the real row count instead.
local function bindScrolling()
  local list = findWidget('cardList')
  local bar = findWidget('cardScroll')
  if not list or not bar then
    return
  end

  connect(bar, {
    onValueChange = function(_, value)
      if suppressScrollEvent then
        return
      end
      scrollValue = value
      applyScroll()
    end,
  })

  -- The wheel over the cards. Handed straight to the bar so the wheel, the
  -- arrows and a thumb drag all travel at the same rate and all arrive through
  -- the one onValueChange path above.
  list.onMouseWheel = function(_, _, direction)
    if not bar:isOn() then
      return false
    end
    if direction == MouseWheelUp then
      bar:decrement()
    else
      bar:increment()
    end
    return true
  end

  -- A taller panel needs more pooled cards and has less left to scroll.
  -- Nothing resizes this window today; this is what keeps the pool size from
  -- being a silent assumption about that.
  --
  -- (!) Height only. This fires on every move as well as every resize, and a
  -- move changes nothing here -- reacting to it would refill fifteen cards on
  -- each frame of a window drag.
  list.onGeometryChange = function(_, oldRect, newRect)
    if not state or oldRect.height == newRect.height then
      return
    end
    resizePool(list, poolRowsNeeded(list))
    updateScrollRange(list, bar)
    poolFirstRow = -1
    applyScroll()
  end
end

-- A character change must not leave the last character's achievements on
-- screen or in memory. Same pattern as game_bazaar's onGameEnd: hide, then
-- forget everything that belongs to the character who logged out. show()
-- then says "Fetching your achievements..." until the new sync arrives.
-- The highscore board itself is server-wide and is refetched on every open;
-- only the "your rank" line is per character, so only it is blanked.
local function onGameEnd()
  hide()
  if searchEvent then
    removeEvent(searchEvent)
    searchEvent = nil
  end
  if statusEvent then
    removeEvent(statusEvent)
    statusEvent = nil
  end

  state = nil
  secrets = {}
  invalidateCatalogue()

  -- Hide the old character's cards. The pool widgets stay (they are reused).
  visible = {}
  bindPool(0, true)
  poolFirstRow = -1
  scrollValue = 0

  if hsPanel then
    local you = hsPanel:recursiveGetChildById('youText')
    if you then
      you:setText('')
    end
  end
end

function init()
  g_ui.importStyle('achievements')
  window = g_ui.createWidget('AchWindow', rootWidget)
  window:hide()

  -- Two tabs on one window. Highscores is added FIRST because UITabBar
  -- selects tab one on creation, which is what makes it the primary view
  -- without a separate selectTab call.
  --
  -- The panels are created detached and handed to addTab, which parents the
  -- selected one into `tabContent` -- the same pattern game_market uses.
  --
  -- (!) They must exist BEFORE populateFilters and bindScrolling below, which
  -- reach into the achievements panel through findWidget. And the unselected
  -- panel stays unparented, which is why those lookups go through findWidget
  -- rather than through `window` -- see the note on the declarations.
  hsPanel = g_ui.createWidget('HsTabPanel')
  achPanel = g_ui.createWidget('AchTabPanel')

  local tabs = window:getChildById('mainTabs')
  tabs:setContentWidget(window:getChildById('tabContent'))

  -- Icons come from the side-button rail rather than from new art: the tab and
  -- the button that opens this window should not be two different pictures of
  -- the same thing.
  -- The icon's room is the button style's left padding, which addTab already
  -- counts, so no width fixing is needed here. See RecordsTabBarButton.
  tabs:addTab(tr('Highscores'), hsPanel, '/game_sidebuttons/buttons/skills.png')
  tabs:addTab(tr('Achievements'), achPanel, '/game_sidebuttons/buttons/achievements.png')

  -- The status line reports achievement actions ("Showcasing X on your
  -- character page"), so it belongs to that tab and is hidden on the other --
  -- on the Highscores tab it was a stale sentence about a different view.
  local function syncTabChrome(tab)
    local status = window:getChildById('statusLine')
    if status then
      status:setVisible(tab ~= nil and tab.tabPanel == achPanel)
    end
  end

  tabs.onTabChange = function(_, tab)
    syncTabChrome(tab)
  end
  syncTabChrome(tabs:getCurrentTab())

  stopFocusScrolling()
  bindScrolling()
  populateFilters()

  -- No button is created here. game_sidebuttons already carries an
  -- `achievementsButton` on the same rail as Bao and the Bazaar, and it was
  -- written to call modules.game_achievements.toggle() before this module
  -- existed. Adding a top-menu button as well would give one window two
  -- entry points in two different places.
  ProtocolGame.registerOpcode(OPCODE_ACHIEVEMENTS_SEND, onAchievementsOpcode)
  connect(g_game, { onGameEnd = onGameEnd })
end

function terminate()
  disconnect(g_game, { onGameEnd = onGameEnd })
  ProtocolGame.unregisterOpcode(OPCODE_ACHIEVEMENTS_SEND)
  if searchEvent then
    removeEvent(searchEvent)
    searchEvent = nil
  end
  if statusEvent then
    removeEvent(statusEvent)
    statusEvent = nil
  end
  if window then
    window:destroy()
    window = nil
  end
  -- The tab panels are destroyed by their tab buttons (UITabBar sets
  -- tab.onDestroy), which went with the window. Only the references are
  -- cleared here; destroying them again would be a double free.
  hsPanel = nil
  achPanel = nil
  hs = nil
  hsRows = {}
  -- (!) Cleared with the window. fillBoardButtons keeps its widgets when the
  -- signature matches, so a stale one would skip the rebuild on the next open
  -- and then look up children of a row that no longer has any.
  boardButtonSignature = nil
  state = nil
  secrets = {}
  -- The cards went with the window; the pool must not outlive them.
  pool = {}
  visible = {}
  poolFirstRow = -1
  scrollValue = 0
  invalidateCatalogue()
end

function hide()
  if not window then
    return
  end
  window:hide()
end

function show()
  if not window then
    return
  end
  sendAction(ACTION_REQUEST_SYNC)

  -- Highscores are refetched on every open rather than cached client-side:
  -- unlike the achievement list, which only changes when THIS character does
  -- something, a board changes because anyone on the server did. The server
  -- caches the query for a minute, so an open costs at most one scan.
  requestHighscores(hs and hs.board or DEFAULT_BOARD, hs and hs.vocation or 0, 1)

  window:show()
  window:raise()
  window:focus()

  if not hs then
    hsPanel:recursiveGetChildById('hsNotice'):setText('Fetching the highscores...')
    hsPanel:recursiveGetChildById('hsNotice'):show()
  end
  if not state then
    findWidget('emptyNotice'):setText('Fetching your achievements...')
    findWidget('emptyNotice'):show()
  end
end

function toggle()
  if not window then
    return
  end
  if window:isVisible() then
    hide()
  else
    show()
  end
end
